1	// Package placement parses raw placement request bodies into the input
2	// object accepted by service.Accept. It is a standalone entry point: it has
3	// no dependency on the HTTP transport, opens no database, and performs no
4	// scheduling or writes. The HTTP API and direct callers share exactly these
5	// strict rules.
6	package placement
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"errors"
12		"io"
13		"strconv"
14		"strings"
15	
16		"github.com/Bob-xisuke/orb-scheduler-core/internal/model"
17	)
18	
19	// ErrInvalidPlacementInput is the single sentinel returned for every parse
20	// failure: malformed JSON, a non-object root, trailing data, unknown or
21	// duplicate member names, missing required fields, explicit nulls, type or
22	// range errors, and duplicate node names. Callers classify failures with
23	// errors.Is; a failed parse never yields a partial input object.
24	var ErrInvalidPlacementInput = errors.New("invalid placement input")
25	
26	// ---------------------------------------------------------------------------
27	// Strict request parsing.
28	//
29	// readStrictObject/readObjectMembers below are the single definition of the
30	// object-member rules shared by the top-level request body and every nested
31	// object (resources, node, selector, labels):
32	//   - the value is exactly one JSON object,
33	//   - no unknown or duplicate member names (member names are compared after
34	//     escape decoding, so a name also collides with its escaped spellings),
35	//   - each value is captured raw for the field-specific rules that follow.
36	//
37	// ParsePlacementInput adds the root-level rules on top of that shared walk:
38	// no trailing data after the root object, every required member present, each
39	// field's declared JSON type and range (null is never accepted where a value
40	// is required), and unique node names. Defaults for omitted selector/labels
41	// are not a parser rule: they come from model.NormalizeInput, the single
42	// definition shared with acceptance and content comparison.
43	// ---------------------------------------------------------------------------
44	
45	var topLevelFields = map[string]bool{
46		"namespace": true,
47		"name":      true,
48		"queue":     true,
49		"priority":  true,
50		"resources": true,
51		"selector":  true,
52		"nodes":     true,
53	}
54	
55	var resourceFields = map[string]bool{"cpu": true, "memory": true}
56	
57	var nodeFields = map[string]bool{
58		"name":   true,
59		"cpu":    true,
60		"memory": true,
61		"labels": true,
62	}
63	
64	// ParsePlacementInput decodes one placement request body. On success it
65	// returns the complete input object, ready for service.Accept: every input
66	// field keeps its submitted value, the node array keeps its order, omitted
67	// selector and node labels are filled as empty objects through the shared
68	// model.NormalizeInput rules, and an empty nodes array stays an empty array.
69	// On any rule violation it returns nil and an error matching
70	// errors.Is(err, ErrInvalidPlacementInput).
71	func ParsePlacementInput(body []byte) (*model.Placement, error) {
72		dec := json.NewDecoder(bytes.NewReader(body))
73	
74		fields, err := readStrictObject(dec, topLevelFields)
75		if err != nil {
76			return nil, err
77		}
78		if _, err := dec.Token(); !errors.Is(err, io.EOF) {
79			return nil, ErrInvalidPlacementInput // trailing data
80		}
81	
82		for _, required := range []string{"namespace", "name", "queue", "priority", "resources", "nodes"} {
83			if _, ok := fields[required]; !ok {
84				return nil, ErrInvalidPlacementInput
85			}
86		}
87	
88		p := &model.Placement{}
89		if p.Namespace, err = parseTrimmedString(fields["namespace"]); err != nil {
90			return nil, err
91		}
92		if p.Name, err = parseTrimmedString(fields["name"]); err != nil {
93			return nil, err
94		}
95		if p.Queue, err = parseTrimmedString(fields["queue"]); err != nil {
96			return nil, err
97		}
98		priority, err := parseBoundedInt(fields["priority"], 32)
99		if err != nil {
100			return nil, err
101		}
102		p.Priority = int32(priority)
103		if p.Resources, err = parseResources(fields["resources"]); err != nil {
104			return nil, err
105		}
106		if p.Nodes, err = parseNodes(fields["nodes"]); err != nil {
107			return nil, err
108		}
109		if raw, ok := fields["selector"]; ok {
110			if p.Selector, err = parseStringMap(raw); err != nil {
111				return nil, err
112			}
113		}
114		// Omitted selector/labels get their defaults from the single shared
115		// definition, not from a parser-local copy of the rules.
116		model.NormalizeInput(p)
117		return p, nil
118	}
119	
120	func parseResources(raw json.RawMessage) (model.Resources, error) {
121		var r model.Resources
122		obj, err := parseStrictObject(raw, resourceFields)
123		if err != nil {
124			return r, err
125		}
126		cpuRaw, ok := obj["cpu"]
127		if !ok {
128			return r, ErrInvalidPlacementInput
129		}
130		memoryRaw, ok := obj["memory"]
131		if !ok {
132			return r, ErrInvalidPlacementInput
133		}
134		cpu, err := parseBoundedInt(cpuRaw, 64)
135		if err != nil || cpu <= 0 {
136			return r, ErrInvalidPlacementInput
137		}
138		memory, err := parseBoundedInt(memoryRaw, 64)
139		if err != nil || memory <= 0 {
140			return r, ErrInvalidPlacementInput
141		}
142		return model.Resources{CPU: cpu, Memory: memory}, nil
143	}
144	
145	func parseNodes(raw json.RawMessage) ([]model.Node, error) {
146		if isNull(raw) {
147			return nil, ErrInvalidPlacementInput
148		}
149		dec := json.NewDecoder(bytes.NewReader(raw))
150		tok, err := dec.Token()
151		if err != nil {
152			return nil, ErrInvalidPlacementInput
153		}
154		if d, ok := tok.(json.Delim); !ok || d != '[' {
155			return nil, ErrInvalidPlacementInput
156		}
157	
158		nodes := []model.Node{}
159		names := map[string]bool{}
160		for dec.More() {
161			var elem json.RawMessage
162			if err := dec.Decode(&elem); err != nil {
163				return nil, ErrInvalidPlacementInput
164			}
165			obj, err := parseStrictObject(elem, nodeFields)
166			if err != nil {
167				return nil, err
168			}
169			nameRaw, ok := obj["name"]
170			if !ok {
171				return nil, ErrInvalidPlacementInput
172			}
173			cpuRaw, ok := obj["cpu"]
174			if !ok {
175				return nil, ErrInvalidPlacementInput
176			}
177			memoryRaw, ok := obj["memory"]
178			if !ok {
179				return nil, ErrInvalidPlacementInput
180			}
181			name, err := parseTrimmedString(nameRaw)
182			if err != nil {
183				return nil, err
184			}
185			cpu, err := parseBoundedInt(cpuRaw, 64)
186			if err != nil || cpu < 0 {
187				return nil, ErrInvalidPlacementInput
188			}
189			memory, err := parseBoundedInt(memoryRaw, 64)
190			if err != nil || memory < 0 {
191				return nil, ErrInvalidPlacementInput
192			}
193			labels := map[string]string(nil)
194			if labelRaw, ok := obj["labels"]; ok {
195				labels, err = parseStringMap(labelRaw)
196				if err != nil {
197					return nil, err
198				}
199			}
200			if names[name] {
201				return nil, ErrInvalidPlacementInput
202			}
203			names[name] = true
204			nodes = append(nodes, model.Node{Name: name, CPU: cpu, Memory: memory, Labels: labels})
205		}
206		if _, err := dec.Token(); err != nil {
207			return nil, ErrInvalidPlacementInput // closing ']'
208		}
209		return nodes, nil
210	}
211	
212	// readStrictObject consumes exactly one JSON object from dec and returns its
213	// members with their values still raw. Together with readObjectMembers it is
214	// the single definition of the member rules: member names are restricted to
215	// allowed (nil allows any names), and unknown and duplicate names are
216	// rejected before the duplicate value can overwrite anything.
217	func readStrictObject(dec *json.Decoder, allowed map[string]bool) (map[string]json.RawMessage, error) {
218		tok, err := dec.Token()
219		if err != nil {
220			return nil, ErrInvalidPlacementInput
221		}
222		if d, ok := tok.(json.Delim); !ok || d != '{' {
223			return nil, ErrInvalidPlacementInput
224		}
225		return readObjectMembers(dec, allowed)
226	}
227	
228	// parseStrictObject applies the shared member rules to a raw nested object.
229	func parseStrictObject(raw json.RawMessage, allowed map[string]bool) (map[string]json.RawMessage, error) {
230		if isNull(raw) {
231			return nil, ErrInvalidPlacementInput
232		}
233		return readStrictObject(json.NewDecoder(bytes.NewReader(raw)), allowed)
234	}
235	
236	// parseStringMap decodes an object with arbitrary string keys and string
237	// values; null or non-string values are rejected.
238	func parseStringMap(raw json.RawMessage) (map[string]string, error) {
239		raws, err := parseStrictObject(raw, nil)
240		if err != nil {
241			return nil, err
242		}
243		out := map[string]string{}
244		for key, value := range raws {
245			s, err := parseJSONString(value)
246			if err != nil {
247				return nil, err
248			}
249			out[key] = s
250		}
251		return out, nil
252	}
253	
254	func readObjectMembers(dec *json.Decoder, allowed map[string]bool) (map[string]json.RawMessage, error) {
255		out := map[string]json.RawMessage{}
256		for dec.More() {
257			keyTok, err := dec.Token()
258			if err != nil {
259				return nil, ErrInvalidPlacementInput
260			}
261			key, ok := keyTok.(string)
262			if !ok {
263				return nil, ErrInvalidPlacementInput
264			}
265			if allowed != nil && !allowed[key] {
266				return nil, ErrInvalidPlacementInput
267			}
268			if _, dup := out[key]; dup {
269				return nil, ErrInvalidPlacementInput
270			}
271			var value json.RawMessage
272			if err := dec.Decode(&value); err != nil {
273				return nil, ErrInvalidPlacementInput
274			}
275			out[key] = value
276		}
277		if _, err := dec.Token(); err != nil {
278			return nil, ErrInvalidPlacementInput // closing '}'
279		}
280		return out, nil
281	}
282	
283	// parseTrimmedString accepts a JSON string that is non-empty and has no
284	// leading or trailing Unicode whitespace.
285	func parseTrimmedString(raw json.RawMessage) (string, error) {
286		s, err := parseJSONString(raw)
287		if err != nil {
288			return "", err
289		}
290		if s == "" || s != strings.TrimSpace(s) {
291			return "", ErrInvalidPlacementInput
292		}
293		return s, nil
294	}
295	
296	func parseJSONString(raw json.RawMessage) (string, error) {
297		if isNull(raw) {
298			return "", ErrInvalidPlacementInput
299		}
300		var s string
301		if err := json.Unmarshal(raw, &s); err != nil {
302			return "", ErrInvalidPlacementInput
303		}
304		return s, nil
305	}
306	
307	// parseBoundedInt accepts an integral JSON number without fraction or exponent
308	// that fits a signed integer of the given bit size (32 or 64).
309	func parseBoundedInt(raw json.RawMessage, bitSize int) (int64, error) {
310		if isNull(raw) {
311			return 0, ErrInvalidPlacementInput
312		}
313		dec := json.NewDecoder(bytes.NewReader(raw))
314		dec.UseNumber()
315		var value any
316		if err := dec.Decode(&value); err != nil {
317			return 0, ErrInvalidPlacementInput
318		}
319		number, ok := value.(json.Number)
320		if !ok {
321			return 0, ErrInvalidPlacementInput
322		}
323		n, err := strconv.ParseInt(number.String(), 10, bitSize)
324		if err != nil {
325			return 0, ErrInvalidPlacementInput
326		}
327		return n, nil
328	}
329	
330	func isNull(raw json.RawMessage) bool {
331		return bytes.Equal(bytes.TrimSpace(raw), []byte("null"))
332	}
333

