1	// Package fakestore provides an in-memory implementation of the storage
2	// contract defined by package service. It lets business-logic tests run the
3	// real accept and query flows without creating a SQLite file: stored records
4	// are controlled by the test, every call is recorded, and each method can be
5	// switched to fail with a chosen error. It carries no scheduling, defaulting
6	// or comparison rules of its own — those stay in package service.
7	package fakestore
8	
9	import (
10		"context"
11		"encoding/json"
12		"fmt"
13		"sort"
14		"sync"
15	
16		"github.com/Bob-xisuke/orb-scheduler-core/internal/model"
17	)
18	
19	// SubmitCall records one Submit invocation.
20	type SubmitCall struct {
21		// Record is a deep copy of the placement as the service submitted it,
22		// after its own normalization and trial scheduling.
23		Record *model.Placement
24	}
25	
26	// GetCall records one Get invocation.
27	type GetCall struct {
28		Namespace string
29		Name      string
30	}
31	
32	// Store is an in-memory storage double. The zero value is ready to use and
33	// safe for concurrent use.
34	//
35	// Its default behavior mirrors the storage guarantees the service relies on:
36	//   - Submit keeps the first record stored for a (namespace, name) identity
37	//     and answers later submissions of that identity with the kept record
38	//     and created false;
39	//   - Get returns model.ErrNotFound for an unknown identity;
40	//   - List intersects the non-empty filter fields (a node filter never
41	//     matches a rejected record) and sorts by namespace then name in UTF-8
42	//     byte order.
43	//
44	// Setting SubmitErr, GetErr or ListErr makes the matching method fail with
45	// that error instead of touching the in-memory records. Records can be
46	// preloaded with Seed, which is not counted as a call. Every Submit, Get and
47	// List invocation is appended to Submits, Gets and Lists.
48	type Store struct {
49		mu      sync.Mutex
50		records map[identity]*model.Placement
51		order   []identity
52	
53		SubmitErr error
54		GetErr    error
55		ListErr   error
56	
57		Submits []SubmitCall
58		Gets    []GetCall
59		Lists   []model.ListFilter
60	}
61	
62	type identity struct {
63		namespace string
64		name      string
65	}
66	
67	// Seed preloads records as if they had been registered earlier, without
68	// recording calls. The first record for an identity wins, matching Submit.
69	func (s *Store) Seed(records ...*model.Placement) {
70		s.mu.Lock()
71		defer s.mu.Unlock()
72		for _, rec := range records {
73			id := identity{rec.Namespace, rec.Name}
74			if s.records == nil {
75				s.records = map[identity]*model.Placement{}
76			}
77			if _, ok := s.records[id]; ok {
78				continue
79			}
80			s.records[id] = clone(rec)
81			s.order = append(s.order, id)
82		}
83	}
84	
85	// Submit implements the service storage contract: it stores a copy of p the
86	// first time its identity is seen and otherwise returns the kept record.
87	func (s *Store) Submit(_ context.Context, p *model.Placement) (*model.Placement, bool, error) {
88		s.mu.Lock()
89		defer s.mu.Unlock()
90		s.Submits = append(s.Submits, SubmitCall{Record: clone(p)})
91		if s.SubmitErr != nil {
92			return nil, false, s.SubmitErr
93		}
94		id := identity{p.Namespace, p.Name}
95		if existing, ok := s.records[id]; ok {
96			return clone(existing), false, nil
97		}
98		if s.records == nil {
99			s.records = map[identity]*model.Placement{}
100		}
101		s.records[id] = clone(p)
102		s.order = append(s.order, id)
103		return clone(p), true, nil
104	}
105	
106	// Get implements the service storage contract: it returns a copy of the
107	// stored record or model.ErrNotFound for an unknown identity.
108	func (s *Store) Get(_ context.Context, namespace, name string) (*model.Placement, error) {
109		s.mu.Lock()
