package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strings"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/model"
)

// Submit stores p the first time its (namespace, name) identity is seen. On a
// repeated submission it returns the previously stored record. created reports
// whether the row was inserted by this call.
func (s *Store) Submit(ctx context.Context, p *Placement) (stored *Placement, created bool, err error) {
	payload, err := model.CanonicalInput(p)
	if err != nil {
		return nil, false, fmt.Errorf("encode placement: %w", err)
	}

	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return nil, false, fmt.Errorf("begin submit: %w", err)
	}
	defer tx.Rollback()

	_, execErr := tx.ExecContext(ctx,
		"INSERT INTO placements (namespace, name, input_json, status, node, reason) VALUES (?, ?, ?, ?, ?, ?)",
		p.Namespace, p.Name, string(payload), p.Status, p.Node, p.Reason,
	)
	if execErr == nil {
		if err := tx.Commit(); err != nil {
			return nil, false, fmt.Errorf("commit submit: %w", err)
		}
		out := *p
		return &out, true, nil
	}
	if !isUniqueViolation(execErr) {
		return nil, false, fmt.Errorf("insert placement: %w", execErr)
	}

	row := tx.QueryRowContext(ctx,
		"SELECT input_json, status, node, reason FROM placements WHERE namespace = ? AND name = ?",
		p.Namespace, p.Name,
	)
	var inputJSON, status string
	var node, reason sql.NullString
	if err := row.Scan(&inputJSON, &status, &node, &reason); err != nil {
		return nil, false, fmt.Errorf("load existing placement: %w", err)
	}
	existing, err := decodeRecord(inputJSON, status, node, reason)
	if err != nil {
		return nil, false, err
	}
	return existing, false, nil
}

// Get fetches a single placement by its identity. It returns ErrNotFound when
// the identity is unknown.
func (s *Store) Get(ctx context.Context, namespace, name string) (*Placement, error) {
	row := s.db.QueryRowContext(ctx,
		"SELECT input_json, status, node, reason FROM placements WHERE namespace = ? AND name = ?",
		namespace, name,
	)
	var inputJSON, status string
	var node, reason sql.NullString
	if err := row.Scan(&inputJSON, &status, &node, &reason); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("get placement: %w", err)
	}
	return decodeRecord(inputJSON, status, node, reason)
}

// List returns committed placements matching f, sorted by namespace then name
// in UTF-8 byte order (SQLite BINARY text ordering).
func (s *Store) List(ctx context.Context, f ListFilter) ([]*Placement, error) {
	var clauses []string
	var args []any
	if f.Namespace != "" {
		clauses = append(clauses, "namespace = ?")
		args = append(args, f.Namespace)
	}
	if f.Queue != "" {
		clauses = append(clauses, "queue = ?")
		args = append(args, f.Queue)
	}
	if f.Node != "" {
		clauses = append(clauses, "node = ?")
		args = append(args, f.Node)
	}
	query := "SELECT input_json, status, node, reason FROM placements"
	if len(clauses) > 0 {
		query += " WHERE " + strings.Join(clauses, " AND ")
	}
	query += " ORDER BY namespace, name"

	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("list placements: %w", err)
	}
	defer rows.Close()

	var out []*Placement
	for rows.Next() {
		var inputJSON, status string
		var node, reason sql.NullString
		if err := rows.Scan(&inputJSON, &status, &node, &reason); err != nil {
			return nil, fmt.Errorf("scan placement: %w", err)
		}
		rec, err := decodeRecord(inputJSON, status, node, reason)
		if err != nil {
			return nil, err
		}
		out = append(out, rec)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate placements: %w", err)
	}
	return out, nil
}

func decodeRecord(inputJSON, status string, node, reason sql.NullString) (*Placement, error) {
	p, err := model.DecodeInput([]byte(inputJSON))
	if err != nil {
		return nil, fmt.Errorf("decode stored placement: %w", err)
	}
	p.Status = status
	if node.Valid {
		v := node.String
		p.Node = &v
	}
	if reason.Valid {
		v := reason.String
		p.Reason = &v
	}
	return p, nil
}

func isUniqueViolation(err error) bool {
	msg := strings.ToLower(err.Error())
	return strings.Contains(msg, "unique constraint failed")
}

// Package store owns the SQLite file and every write the service performs.
package store

import (
	"database/sql"
	"fmt"

	_ "modernc.org/sqlite"
)

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db *sql.DB
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	// Serialize access through one connection: combined with WAL this keeps
	// concurrent submissions free of busy errors while the UNIQUE constraint
	// remains the guarantee that one identity is stored exactly once.
	db.SetMaxOpenConns(1)
	if _, err := db.Exec("PRAGMA busy_timeout=5000"); err != nil {
		db.Close()
		return nil, fmt.Errorf("set busy timeout: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

const schema = `
CREATE TABLE IF NOT EXISTS service_metadata (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS placements (
	namespace  TEXT NOT NULL,
	name       TEXT NOT NULL,
	input_json TEXT NOT NULL,
	status     TEXT NOT NULL,
	node       TEXT,
	reason     TEXT,
	queue      TEXT NOT NULL GENERATED ALWAYS AS (json_extract(input_json, '$.queue')) VIRTUAL,
	PRIMARY KEY (namespace, name)
);

CREATE INDEX IF NOT EXISTS idx_placements_ns   ON placements (namespace);
CREATE INDEX IF NOT EXISTS idx_placements_queue ON placements (queue);
CREATE INDEX IF NOT EXISTS idx_placements_node  ON placements (node);
`

package api

import (
	"errors"
	"io"
	"net/http"
	"net/url"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/placement"
	"github.com/Bob-xisuke/orb-scheduler-core/internal/service"
)

// Error codes published by the placements API.
const (
	codeInvalidInput = "InvalidPlacementInputError"
	codeNotFound     = "PlacementNotFoundError"
	codeConflict     = "PlacementConflictError"
	codeStorageDown  = "storage_unavailable"
)

type placementHandler struct {
	svc *service.Service
}

func writeAPIError(c *gin.Context, status int, code, message string) {
	c.AbortWithStatusJSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

// createPlacement handles POST /v1/placements. The transport layer only
// parses and validates the request and maps the business acceptance outcome
// to its HTTP status; scheduling and idempotency/conflict decisions belong to
// service.Accept. The strict parsing rules live in package placement and are
// shared with direct, non-HTTP callers.
func (h *placementHandler) createPlacement(c *gin.Context) {
	body, err := io.ReadAll(c.Request.Body)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement input")
		return
	}
	p, err := placement.ParsePlacementInput(body)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement input")
		return
	}

	stored, outcome, err := h.svc.Accept(c.Request.Context(), p)
	if err != nil {
		writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
		return
	}
	switch outcome {
	case service.Created:
		c.JSON(http.StatusCreated, stored)
	case service.Identical:
		c.JSON(http.StatusOK, stored)
	case service.Conflict:
		writeAPIError(c, http.StatusConflict, codeConflict,
			"a placement with this namespace and name already exists with different content")
	}
}

// listPlacements handles GET /v1/placements, both the single-record form
// (namespace+name) and the filtered-list form. The transport layer only
// decodes the raw query string and maps the business result to its HTTP
// status; all parameter rules and filtering belong to service.Query.
func (h *placementHandler) listPlacements(c *gin.Context) {
	values, err := url.ParseQuery(c.Request.URL.RawQuery)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
		return
	}

	result, err := h.svc.Query(c.Request.Context(), values)
	if errors.Is(err, service.ErrInvalidPlacementQuery) {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
		return
	}
	if errors.Is(err, service.ErrPlacementNotFound) {
		writeAPIError(c, http.StatusNotFound, codeNotFound, "placement not found")
		return
	}
	if err != nil {
		writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
		return
	}
	if result.Record != nil {
		c.JSON(http.StatusOK, result.Record)
		return
	}
	c.JSON(http.StatusOK, gin.H{"items": result.Items})
}

package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/service"
	"github.com/Bob-xisuke/orb-scheduler-core/internal/store"
)

// NewRouter wires the public HTTP surface: health and the placements API. Every
// entry keeps the error shape described in README.md.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	h := &placementHandler{svc: service.New(st)}
	router.POST("/v1/placements", h.createPlacement)
	router.GET("/v1/placements", h.listPlacements)

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

