224	func TestConcurrentIdenticalSubmissionsStoreOneRecord(t *testing.T) {
225		_, h := newTestRouter(t)
226		const n = 24
227		var wg sync.WaitGroup
228		statuses := make([]int, n)
229		wg.Add(n)
230		for i := 0; i < n; i++ {
231			go func(i int) {
