286	
287	func TestListFiltersAndSortsByNamespaceThenName(t *testing.T) {
288		_, h := newTestRouter(t)
289		submit := func(ns, name, queue, node string) {
290			t.Helper()
291			body := fmt.Sprintf(`{
292			  "namespace": %q, "name": %q, "queue": %q, "priority": 0,
293			  "resources": {"cpu": 1, "memory": 1},
294			  "nodes": [{"name": %q, "cpu": 10, "memory": 10, "labels": {}}]
295			}`, ns, name, queue, node)
296			if rec := postPlacement(t, h, body); rec.Code != http.StatusCreated {
297				t.Fatalf("create %s/%s: %d %s", ns, name, rec.Code, rec.Body.String())
298			}
299		}
300		// UTF-8 byte order: 'a'(0x61) < 'z'(0x7A) < 'ä'(0xC3..) < '日'(0xE6..).
301		submit("z", "n2", "q1", "host-1")
302		submit("a", "n2", "q1", "host-1")
303		submit("ä", "n1", "q2", "host-2")
304		submit("日", "n1", "q1", "host-1")
305		submit("a", "n1", "q2", "host-2")
306	
307		all := doRequest(t, h, http.MethodGet, "/v1/placements", "")
308		var order []string
309		for _, item := range decodeBody(t, all)["items"].([]any) {
310			m := item.(map[string]any)
311			order = append(order, m["namespace"].(string)+"/"+m["name"].(string))
312		}
313		want := []string{"a/n1", "a/n2", "z/n2", "ä/n1", "日/n1"}
314		if fmt.Sprint(order) != fmt.Sprint(want) {
315			t.Fatalf("order = %v, want %v", order, want)
316		}
317	
318		byQueue := doRequest(t, h, http.MethodGet, "/v1/placements?queue=q2", "")
319		if len(decodeBody(t, byQueue)["items"].([]any)) != 2 {
320			t.Fatalf("queue filter: %s", byQueue.Body.String())
321		}
322		byNode := doRequest(t, h, http.MethodGet, "/v1/placements?node=host-2&queue=q2", "")
323		if len(decodeBody(t, byNode)["items"].([]any)) != 2 {
324			t.Fatalf("node+queue intersection: %s", byNode.Body.String())
325		}
326		byNamespace := doRequest(t, h, http.MethodGet, "/v1/placements?namespace=a", "")
327		if len(decodeBody(t, byNamespace)["items"].([]any)) != 2 {
328			t.Fatalf("namespace filter: %s", byNamespace.Body.String())
329		}
330		empty := doRequest(t, h, http.MethodGet, "/v1/placements?queue=nope", "")
331		if got := decodeBody(t, empty)["items"].([]any); len(got) != 0 {
332			t.Fatalf("want empty items, got %v", got)
333		}
334	}
335	
336	func TestInvalidQueryParams(t *testing.T) {
337		_, h := newTestRouter(t)
338		for _, target := range []string{
339			"/v1/placements?unknown=1",
340			"/v1/placements?namespace=",
341			"/v1/placements?namespace=a&namespace=b",
342			"/v1/placements?name=x&queue=q",
343			"/v1/placements?%zz",
