349	
350	func TestInvalidBodies(t *testing.T) {
351		_, h := newTestRouter(t)
352		valid := func() string {
353			body := map[string]any{
354				"namespace": "ns", "name": "job", "queue": "q", "priority": 1,
355				"resources": map[string]any{"cpu": 100, "memory": 64},
356				"nodes":     []any{map[string]any{"name": "n1", "cpu": 100, "memory": 64, "labels": map[string]any{}}},
357			}
358			data, _ := json.Marshal(body)
359			return string(data)
360		}
361	
362		rawCases := []string{
363			``,
364			`not json`,
365			`[]`,
366			`null`,
367			`123`,
368			valid() + ` {"x":1}`, // trailing data
369			valid() + `tail`,
370			`{"namespace":"ns","name":"job","queue":"q","priority":1,
371			  "resources":{"cpu":100,"memory":64},
372			  "nodes":[],"unknown":true}`,
373			`{"namespace":"ns","name":"job","queue":"q","priority":1,
374			  "resources":{"cpu":100,"memory":64},"nodes":[],"namespace":"ns2"}`, // duplicate key
375			`{"name":"job","queue":"q","priority":1,
376			  "resources":{"cpu":100,"memory":64},"nodes":[]}`, // missing namespace
377			`{"namespace":"ns","name":"job","queue":"q","priority":1,
378			  "resources":{"cpu":100},"nodes":[]}`, // missing memory
379			`{"namespace":"ns","name":"job","queue":"q","priority":1,
380			  "resources":{"cpu":100,"memory":64,"extra":1},"nodes":[]}`, // unknown resource field
381			`{"namespace":"ns","name":"job","queue":"q","priority":1,
382			  "resources":{"cpu":100,"memory":64},
383			  "nodes":[{"name":"n1","cpu":100,"memory":64,"labels":{},"x":1}]}`, // unknown node field
384			`{"namespace":"ns","name":"job","queue":"q","priority":1,
385			  "resources":{"cpu":100,"memory":64},
386			  "nodes":[{"name":"n1","cpu":100,"memory":64,"labels":{},"name":"n2"}]}`, // duplicate node key
387			`{"namespace":"","name":"job","queue":"q","priority":1,
388			  "resources":{"cpu":100,"memory":64},"nodes":[]}`, // empty namespace
389			`{"namespace":" ns","name":"job","queue":"q","priority":1,
390			  "resources":{"cpu":100,"memory":64},"nodes":[]}`, // leading whitespace
391			`{"namespace":"ns","name":"job ","queue":"q","priority":1,
392			  "resources":{"cpu":100,"memory":64},"nodes":[]}`, // trailing whitespace
393			`{"namespace":"ns","name":"job","queue":"q","priority":1.5,
394			  "resources":{"cpu":100,"memory":64},"nodes":[]}`, // fractional priority
395			`{"namespace":"ns","name":"job","queue":"q","priority":2147483648,
396			  "resources":{"cpu":100,"memory":64},"nodes":[]}`, // int32 overflow
397			`{"namespace":"ns","name":"job","queue":"q","priority":-2147483649,
398			  "resources":{"cpu":100,"memory":64},"nodes":[]}`, // int32 underflow
399			`{"namespace":"ns","name":"job","queue":"q","priority":"1",
400			  "resources":{"cpu":100,"memory":64},"nodes":[]}`, // string priority
401			`{"namespace":"ns","name":"job","queue":"q","priority":null,
