81		if len(fake.Gets) != 0 || len(fake.Lists) != 0 || len(fake.Submits) != 0 {
82			t.Fatalf("invalid queries reached storage: gets=%d lists=%d submits=%d",
83				len(fake.Gets), len(fake.Lists), len(fake.Submits))
