87	func TestQueryWithFakeSingleRecordReturnedAsStored(t *testing.T) {
88		fake, svc := newFakeService()
89		// The stored decision points at a node the request never offered and
90		// asks for more than any node has: if Query re-scheduled, the record
91		// could not come back like this.
92		seeded := placedRecord("team-a", "job-1", "default", "node-not-offered")
93		seeded.Resources = model.Resources{CPU: 9999, Memory: 9999}
94		fake.Seed(seeded)
95	
96		result, err := svc.Query(context.Background(), mustValues(t, "namespace=team-a&name=job-1"))
97		if err != nil {
