107		}
108		if len(fake.Gets) != 1 || fake.Gets[0] != (fakestore.GetCall{Namespace: "team-a", Name: "job-1"}) {
109			t.Fatalf("gets = %+v, want one get for team-a/job-1", fake.Gets)
110		}
111		if len(fake.Lists) != 0 || len(fake.Submits) != 0 {
112			t.Fatalf("single query must not list or write: %+v %+v", fake.Lists, fake.Submits)
113		}
114	}
115	
116	func TestQueryWithFakeSingleMissingIdentity(t *testing.T) {
117		fake, svc := newFakeService()
118		fake.Seed(placedRecord("team-a", "job-1", "default", "node-a"))
119	
120		result, err := svc.Query(context.Background(), mustValues(t, "namespace=team-a&name=missing"))
121		if !errors.Is(err, ErrPlacementNotFound) {
122			t.Fatalf("err = %v, want ErrPlacementNotFound", err)
123		}
124		if errors.Is(err, ErrStorageUnavailable) {
125			t.Fatalf("not-found misreported as storage failure: %v", err)
126		}
127		if result.Record != nil || result.Items != nil {
128			t.Fatalf("failure must leave both fields nil: %+v", result)
129		}
130	}
131	
