		Namespace: "ns",
		Name:      "job",
		Queue:     "q",
		Priority:  1,
		Resources: Resources{CPU: 100, Memory: 64},
		Selector:  map[string]string{"zone": "cn"},
		Nodes: []Node{
			{Name: "n1", CPU: 200, Memory: 128, Labels: map[string]string{"zone": "cn"}},
			{Name: "n2", CPU: 100, Memory: 64, Labels: map[string]string{}},
