func slice0ID(n []model.Node) uintptr   { return reflect.ValueOf(n).Index(0).Addr().Pointer() }

func TestTmpAliasProbeSQLite(t *testing.T) {
	_, svc := newService(t)
	ctx := context.Background()
	p, err := placement.ParsePlacementInput([]byte(`{
	  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
	  "resources": {"cpu": 100, "memory": 64},
	  "selector": {"zone": "cn"},
	  "nodes": [{"name": "n1", "cpu": 200, "memory": 128, "labels": {"zone": "cn"}}]
	}`))
	if err != nil {
		t.Fatal(err)
	}
	rec, outcome, err := svc.Accept(ctx, p)
	if err != nil || outcome != Created {
		t.Fatalf("accept %d %v", outcome, err)
	}
	t.Logf("SQLITE created: rec==p %v", rec == p)
	t.Logf("SQLITE selector same map: %v", mapID(rec.Selector) == mapID(p.Selector))
	t.Logf("SQLITE nodes[0] same address: %v", slice0ID(rec.Nodes) == slice0ID(p.Nodes))
	t.Logf("SQLITE labels same map: %v", mapID(rec.Nodes[0].Labels) == mapID(p.Nodes[0].Labels))
	t.Logf("SQLITE node ptr == caller-set ptr: %v", rec.Node == p.Node)

	p.Priority = 99
	p.Selector["zone"] = "ZZ"
	p.Nodes[0].Name = "MUTATED"
	p.Nodes[0].Labels["zone"] = "LL"
	t.Logf("SQLITE after caller mutate: rec.Priority=%d selector=%v node0=%s label=%v nodeptr=%s",
		rec.Priority, rec.Selector, rec.Nodes[0].Name, rec.Nodes[0].Labels, *rec.Node)

	got, err := svc.Query(ctx, url.Values{"namespace": {"ns"}, "name": {"job"}})
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("SQLITE re-query: prio=%d selector=%v node0=%s label=%v status=%v picked=%s",
		got.Record.Priority, got.Record.Selector, got.Record.Nodes[0].Name, got.Record.Nodes[0].Labels,
		got.Record.Status, *got.Record.Node)

	got.Record.Priority = 777
	got.Record.Selector["zone"] = "QQ"
	got.Record.Nodes[0].Name = "AGAIN"
	again, err := svc.Query(ctx, url.Values{"namespace": {"ns"}, "name": {"job"}})
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("SQLITE query-obj mutate then re-query: prio=%d selector=%v node0=%s",
		again.Record.Priority, again.Record.Selector, again.Record.Nodes[0].Name)
}

func TestTmpAliasProbeFake(t *testing.T) {
	_, svc := newFakeService()
	ctx := context.Background()
	p, err := placement.ParsePlacementInput([]byte(`{
	  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
	  "resources": {"cpu": 100, "memory": 64},
	  "selector": {"zone": "cn"},
	  "nodes": [{"name": "n1", "cpu": 200, "memory": 128, "labels": {"zone": "cn"}}]
	}`))
	if err != nil {
		t.Fatal(err)
	}
	rec, outcome, err := svc.Accept(ctx, p)
	if err != nil || outcome != Created {
		t.Fatalf("accept %d %v", outcome, err)
	}
	t.Logf("FAKE created: rec==p %v", rec == p)
	t.Logf("FAKE selector same map: %v", mapID(rec.Selector) == mapID(p.Selector))
	t.Logf("FAKE nodes[0] same address: %v", slice0ID(rec.Nodes) == slice0ID(p.Nodes))
	t.Logf("FAKE labels same map: %v", mapID(rec.Nodes[0].Labels) == mapID(p.Nodes[0].Labels))
	t.Logf("FAKE node ptr == caller-set ptr: %v", rec.Node == p.Node)

	p.Priority = 99
	p.Selector["zone"] = "ZZ"
	p.Nodes[0].Name = "MUTATED"
	got, err := svc.Query(ctx, url.Values{"namespace": {"ns"}, "name": {"job"}})
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("FAKE re-query after caller mutate: prio=%d selector=%v node0=%s",
		got.Record.Priority, got.Record.Selector, got.Record.Nodes[0].Name)

	// retry/conflict input alias check: second Accept, inspect returned map identity vs second input
	p2, _ := placement.ParsePlacementInput([]byte(`{
	  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
	  "resources": {"cpu": 100, "memory": 64},
	  "selector": {"zone": "cn"},
	  "nodes": [{"name": "n1", "cpu": 200, "memory": 128, "labels": {"zone": "cn"}}]
	}`))
	rec2, outcome2, _ := svc.Accept(ctx, p2)
	t.Logf("FAKE retry outcome=%d rec2==p2 %v selector-same-as-p2 %v", outcome2, rec2 == p2,
		mapID(rec2.Selector) == mapID(p2.Selector))
}

